struct TreeNode {
    int data;
    double freq;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int val, double f) : data(val), freq(f), left(nullptr), right(nullptr) {}
};

#include <queue>
#include <vector>

struct Compare {
    bool operator()(TreeNode* a, TreeNode* b) {
        return a->freq > b->freq;
    }
};

TreeNode* huffmanBuildTree(int values[], double freqs[], int size) {
    if (size <= 0) return nullptr;

    std::priority_queue<TreeNode*, std::vector<TreeNode*>, Compare> minHeap;

    for (int i = 0; i < size; ++i) {
        minHeap.push(new TreeNode(values[i], freqs[i]));
    }

    while (minHeap.size() > 1) {
        TreeNode* left = minHeap.top();
        minHeap.pop();
        TreeNode* right = minHeap.top();
        minHeap.pop();

        TreeNode* merged = new TreeNode(-1, left->freq + right->freq);
        merged->left = left;
        merged->right = right;

        minHeap.push(merged);
    }

    return minHeap.empty() ? nullptr : minHeap.top();
}

